+					t.Fatalf("attempt %d: error = %v, want enumerate rejection", i+1, err)
+				}
+				want = append(want, tc.wantAttempt...)
+				if got := requests(); !slices.Equal(got, want) {
+					t.Fatalf("FETCH requests = %v, want %v", got, want)
+				}
+			}
+		})
+	}
